class Solution { public boolean isAlienSorted(String[] w,String o) { int[] r=new int[26];for(int i=0;i<26;i++)r[o.charAt(i)-'a']=i;for(int k=1;k<w.length;k++){String a=w[k-1],b=w[k];int i=0;while(i<a.length()&&i<b.length()&&a.charAt(i)==b.charAt(i))i++;if(i==b.length()&&a.length()>b.length())return false;if(i<a.length()&&i<b.length()&&r[a.charAt(i)-'a']>r[b.charAt(i)-'a'])return false;}return true;} }
